365	+  const compList = [...comp].sort((a, b) => a - b);
366	+  for (const i of compList) out[i].follow = i - 1;
367	+  for (const i of ppShuffle(compList.slice(), r).slice(0, Math.round(compList.length * M.child))) out[i].scale = P.childScale;
