375	+  for (const i of ppShuffle(out.map((_, k) => k), r).slice(0, Math.round(n * M.hat))) out[i].flags |= PP_FLAG.hat;
376	+  for (const i of ppShuffle(out.map((_, k) => k), r).slice(0, Math.round(n * M.pack))) out[i].flags |= PP_FLAG.pack;
