+      let visible = 0;
+      for (let i = 0; i < m.count; i++) { if (Math.abs(a[i * 16]) + Math.abs(a[i * 16 + 1]) + Math.abs(a[i * 16 + 2]) > 1e-9) visible++; if (c) shirts.add(`${c[i * 3].toFixed(3)},${c[i * 3 + 1].toFixed(3)},${c[i * 3 + 2].toFixed(3)}`); }
